/* ================= 스프라이트: 치비 고양이 3종 =================
   새 치비 시트(대기 idle · 걷기1 · 걷기2 · 먹기 eat)를 배경 투명 처리하고,
   60프레임 전체에 같은 배율(0.0938)을 써서(앉은 대기 ↔ 선 걷기 ↔ 먹기 체격 유지) 바닥 기준 정렬 +
   같은 (타입,방향)은 포즈가 달라도 같은 좌우 위치를 쓰도록 알파 질량 중심으로 맞춰
   프레임당 64×64 PNG로 넣었어요. (base64 단일 HTML 내장)
   idle2(대기 모션)는 생성 이미지가 아니라 위 idle 프레임을 1~2px만 픽셀 편집한 미세 변형본이라
   idle↔idle2 전환 때 몸통이 1px도 움직이지 않아요. (눈꺼풀 / 꼬리 끝 / 귀 끝만 변화)
   eat(먹는 중)은 입에 생선을 문 앉은 자세라 생선 꼬리/머리만큼 실루엣이 넓어요. 질량 중심 대신
   같은 (타입,방향) idle 실루엣과 몸통이 가장 겹치는 dx를 찾아 놓아서, idle → eat로 바뀔 때
   고양이 몸통이 좌우로 튀지 않아요.
   dir: 0↑ 1→ 2↓ 3← · pose: idle / idle2 / walk1 / walk2 / eat
   CATVIS = 프레임 안에서 고양이가 차지하는 세로 픽셀(감정 표시 높이 기준, 대기값) */
var CATSPR={A:{idle:{0:"",1:"",2:"",3:""},walk1:{0:"",1:"",2:"",3:""},walk2:{0:"",1:"",2:"",3:""},idle2:{0:"",1:"",2:"",3:""},eat:{0:"",1:"",2:"",3:""}},B:{idle:{0:"",1:"",2:"",3:""},walk1:{0:"",1:"",2:"",3:""},walk2:{0:"",1:"",2:"",3:""},idle2:{0:"",1:"",2:"",3:""},eat:{0:"",1:"",2:"",3:""}},C:{idle:{0:"",1:"",2:"",3:""},walk1:{0:"",1:"",2:"",3:""},walk2:{0:"",1:"",2:"",3:""},idle2:{0:"",1:"",2:"",3:""},eat:{0:"",1:"",2:"",3:""}}};
var CATVIS={A:{0:46,1:45,2:47,3:45},B:{0:43,1:42,2:44,3:42},C:{0:46,1:46,2:48,3:46}};
var CATIMG={};
(function(){
  var t,p,d,im;
  for(t in CATSPR){
    CATIMG[t]={};
    for(p in CATSPR[t]){
      CATIMG[t][p]={};
      for(d in CATSPR[t][p]){
        im=new Image();
        im.src="data:image/png;base64,"+CATSPR[t][p][d];
        im._vh=CATVIS[t][d];
        CATIMG[t][p][d]=im;
      }
    }
  }
})();

/* ================= 스프라이트: 검냥이(C) 10프레임 '졸다 화들짝' =================
   downloads/chibi-cat-C-sleep-10f-v2.png (5열×2행) 을 위 치비 고양이와 같은 누끼·바닥 정렬(y=63)로
   잘라 64×64로 넣었어요. 검은 털이 배경 슬레이트와 색거리 16~18밖에 안 돼서 배경 임계값을 12로 낮췄습니다.
     1 말똥(평소) → 2 눈 반쯤 → 3 눈 거의 감음 → 4 눈 감음 → 5 고개 숙임
     → 6 푹 숙여 잠 → 7 최저점(완전히 엎드림) → 8 화들짝(눈 번쩍) → 9 눈 크게 뜨며 진정
     → 10 차분히 복귀 → 다시 1
   9·10번은 v2 시트에서 눈을 감은 채가 아니라 눈을 크게 뜬 채 털만 가라앉으며 진정하는 그림이에요.
   배율 0.136은 기존 C_idle_3과 발·몸통 크기를 맞춘 값(아래 24행 실루엣 IoU 0.981, 44×46 = C_idle_3과 동일).
   시트가 왼쪽을 보고 그려져 있어 dir 3 = 원본, dir 1 = 좌우 반전본이고,
   좌우는 프레임마다 발(아래 24행) 실루엣을 1번 프레임과 겹쳐 보정했어요 — 자고 깰 때 발이 미끄러지지 않아요.
   dir 0(뒷모습)·2(정면)은 시트에 없어서 기존 idle/idle2를 그대로 씁니다. */
var SLEEP10SPR={
0:{3:"",
    1:""},
1:{3:"",
    1:""},
2:{3:"",
    1:""},
3:{3:"",
    1:""},
4:{3:"",
    1:""},
5:{3:"",
    1:""},
6:{3:"",
    1:""},
7:{3:"",
    1:""},
8:{3:"",
    1:""},
9:{3:"",
    1:""}
};
var SLEEP10IMG={};
(function(){
  var f,d,im;
  for(f in SLEEP10SPR){
    SLEEP10IMG[f]={};
    for(d in SLEEP10SPR[f]){
      im=new Image();
      im.src="data:image/png;base64,"+SLEEP10SPR[f][d];
      im._vh=CATVIS.C[d];
      SLEEP10IMG[f][d]=im;
    }
  }
})();
/* 프레임 표시 시간(ms): 말똥(F1) 4초 그대로 있다가 F2..F6 을 0.26·0.30·0.34·0.38·0.42초로
   점점 느리게 꾸벅꾸벅 졸고, 최저점 F7 0.65초 → 화들짝 F8 0.26 → 눈 크게 뜬 진정 F9 0.32
   → 복귀 F10 0.22 → 다시 F1. 한 바퀴 7.15초(4초 대기 + 3.15초 졸음). */
var SLEEP10_HOLD=[4000,260,300,340,380,420,650,260,320,220];
var SLEEP10_PER=7150;
function sleepFrameAt(now,seed){
  var t=((now||0)+(seed||0))%SLEEP10_PER;
  if(t<0) t+=SLEEP10_PER;
  for(var i=0;i<10;i++){ if(t<SLEEP10_HOLD[i]) return i; t-=SLEEP10_HOLD[i]; }
  return 0;
}

/* 고양이는 발밑(gy) 기준으로 그린다. dir: 0↑ 1→ 2↓ 3← */
/* 이동 중이면 턴 애니메이션 진행률(t)에 따라 walk1 ↔ walk2 를 세 번 교차, 정지하면 idle */
function catWalkPose(now,walking){
  if(!walking) return "idle";
  var t=1;
  if(G.pending && G.pending.t0) t=Math.min(1,Math.max(0,(now-G.pending.t0)/ANIM_MS));
  var k=Math.floor(t*3);                 /* 0,1,2,3 → walk1, walk2, walk1, walk2 */
  return (k%2)?"walk2":"walk1";
}
/* ================= 대기 모션(idle ↔ idle2) =================
   정지해 있는 고양이만: 타입별 [idle 표시 ms, idle2 표시 ms] 주기로 두 포즈를 번갈아 그려요.
   - 두 번째 인자는 '실제 시각(now)'이 아니라 '이 고양이가 서 있던 시간(idleElapsed)'이에요.
     그래서 걷다 멈춘 순간·복귀·유인·추격 중에는 항상 주기의 처음(idle)부터 시작해요.
   - state 가 "idle" 이 아니면(return·lured·chase·eat) 항상 "idle" 반환 — 대기 모션 없음.
   - 고양이 인덱스(cat.id)마다 900ms 씩 시차를 둬서 한 화면 고양이들이 같이 깜빡이지 않게 함.
   idle2는 idle 픽셀을 1~2px만 손댄 '초미세' 프레임(몸통·머리·발·외곽선 고정, 흔들림 0):
   A: 눈 깜빡임(정면·좌·우) / 뒷모습은 귀 끝 1px 접힘 — 2.4s / 0.18s
   B: 꼬리 끝 1~2px 살랑 — 0.9s / 0.9s
   C: 나른한 눈(홍채 위쪽만 덮음) + 꼬리 끝 1px — 2.8s / 0.24s */
var CAT_IDLE_CYCLE={A:[2400,180],B:[900,900],C:[2800,240]};
function catIdlePose(cat,idleElapsed){
  if(cat.state&&cat.state!=="idle") return "idle";
  var cyc=CAT_IDLE_CYCLE[cat.type]||CAT_IDLE_CYCLE.A;
  var per=cyc[0]+cyc[1];
  var t=((idleElapsed||0)+(cat.id||0)*900)%per;
  if(t<0) t+=per;
  return (t<cyc[0])?"idle":"idle2";
}
function drawCatAt(g,cx,gy,P,dir,type,now,opt){
  opt=opt||{};
  var pose=opt.pose||"idle";
  var walking=(pose==="walk1"||pose==="walk2");
  var sc=opt.scale||1;
  var ty=CATIMG[type]||CATIMG.A;
  var set=ty?(ty[pose]||ty.idle):null;
  var spr=set?(set[dir|0]||set[2]):null;
  /* 검냥이 10프레임 대기 모션 — 옆모습(dir 1·3)만. 정면(2)·뒷모습(0)은 기존 idle 그대로.
     opt.sleep 은 -1(없음) 또는 0..9 라서 0번(말똥)도 반드시 이 조건으로 들어와야 해요. */
  if(opt.sleep!=null&&opt.sleep>=0&&(dir|0)!==0&&(dir|0)!==2){
    var ss=SLEEP10IMG[opt.sleep];
    if(ss&&ss[dir|0]) spr=ss[dir|0];
  }
  if(!spr||!spr.width) return;                 /* 스프라이트 로드 전 */
  if(!opt.noShadow) shadowPix(g,cx,gy-2*sc,Math.round(13*sc),Math.max(3,Math.round(4*sc)),opt.ghost?0.13:0.26);
  var step=walking&&(Math.floor(now/130)%2);
  var bob=0;
  /* 걷기 밥만: 대기(idle)·먹기(eat) 중에는 위아래 1px 흔들림 없이 고정 */
  if(walking) bob=step?1:0;
  var sq=opt.landSq||0;
  g.save();
  g.translate(Math.round(cx),Math.round(gy-bob));
  if(sc!==1) g.scale(sc,sc);
  /* 착지 스쿼시: 발끝 고정으로 몸을 1~2px 눌러 주어 멈춘 직후의 무게감을 줘요(정수 px 크런치라 도트가 안 깨짐) */
  if(sq) g.drawImage(spr,-Math.round(spr.width/2),-spr.height+1,spr.width,spr.height-sq);
  else g.drawImage(spr,-Math.round(spr.width/2),-spr.height+1);
  g.restore();
  drawCatEmote(g,cx,gy,spr,dir,now,opt);
}

/* 머리 위 감정 표시: ? / ♥ / ! */
function drawCatEmote(g,cx,gy,spr,dir,now,opt){
  if(opt.ghost||opt.noEmote) return;
  var e=opt.emote;
  if(!e) return;
  var top=gy-(spr._vh||48);
  var bx=Math.round(cx)+(dir===3?-2:2), by=top-9;
  if(e==="!"){
    /* 발견 순간(opt.spotT) '뿅!' 팝업 — easeOutBack으로 살짝 부풀었다 안착한 뒤 통통 튐.
       배지 없이 진한 외곽선 + 빨간 몸통 + 왼쪽 하이라이트의 굵은 픽셀 느낌표. */
    var age=(opt.spotT&&now>opt.spotT)?(now-opt.spotT):9999;
    var pop=Math.min(1,age/240);
    var p=pop-1, sc;
    if(pop<1) sc=1+2.9*p*p*p+1.9*p*p;              /* easeOutBack (s=1.9) */
    else sc=1+0.06*Math.sin(now/160);              /* 심장박동처럼 미세한 크기 맥동 */
    var bobY=(pop>=1)?Math.round(Math.sin(now/170)*1.4):0;
    g.save();
    g.globalAlpha=(pop<1)?pop:0.96;
    g.translate(Math.round(bx),Math.round(by+4+bobY));
    g.scale(sc,sc);
    fillRR(g,-4,-13,9,14,2,"#3a0d16");
    fillRR(g,-3,-12,7,12,1,"#ff3b4f");
    pf(g,-2,-11,1,10,"#ffc2ca");
    pf(g,-3,-12,7,1,"#ff8d9c");
    fillRR(g,-4,3,9,8,2,"#3a0d16");
    fillRR(g,-3,4,7,6,1,"#ff3b4f");
    pf(g,-2,5,1,4,"#ffc2ca");
    g.restore();
  }else if(e==="?"){
    /* 느낌표와 같은 굵은 픽셀 스타일: 진한 외곽선 + 호박색 몸통 + 왼쪽 하이라이트.
       발견(!)과 구분되게 호기심은 호박색 — 뜰 때도 같은 '뿅' 팝업. */
    var age2=(opt.emoteT&&now>opt.emoteT)?(now-opt.emoteT):9999;
    var pop2=Math.min(1,age2/240);
    var p2=pop2-1, sc2;
    if(pop2<1) sc2=1+2.9*p2*p2*p2+1.9*p2*p2;
    else sc2=1+0.05*Math.sin(now/210);
    var bobY2=(pop2>=1)?Math.round(Math.sin(now/190)*1.4):0;
    var QM=[".#####.","##...##","##...##",".....##","....##.","...##..","..##...",".......","..##...","..##..."];
    var qw=QM[0].length, qh=QM.length, S=2, mx=-qw*S/2, my=-qh*S+1;
    g.save();
    g.globalAlpha=(pop2<1)?pop2:0.96;
    g.translate(Math.round(bx),Math.round(by+4+bobY2));
    g.scale(sc2,sc2);
    for(var oy=-1;oy<=1;oy++)for(var ox=-1;ox<=1;ox++){
      if(!ox&&!oy) continue;
      g.fillStyle="#33120e";
      for(var r1=0;r1<qh;r1++)for(var i1=0;i1<qw;i1++)
        if(QM[r1][i1]==="#") g.fillRect(Math.round(mx+i1*S+ox),Math.round(my+r1*S+oy),S,S);
    }
    g.fillStyle="#ffb02e";
    for(var r2=0;r2<qh;r2++)for(var i2=0;i2<qw;i2++)
      if(QM[r2][i2]==="#") g.fillRect(Math.round(mx+i2*S),Math.round(my+r2*S),S,S);
    pf(g,mx+3,my+2,2,1,"#ffe9b8"); pf(g,mx+2,my+3,1,2,"#ffe9b8");
    g.restore();
  }else if(e==="heart"){
    var k=(now%1000)/1000;
    var hy=by+5-Math.round(k*9);
    g.save(); g.globalAlpha=1-k*0.75;
    var hx=bx+Math.round(Math.sin(now/300)*2);
    fillRR(g,hx-5,hy-1,11,11,3,"rgba(42,10,16,0.55)");
    pf(g,hx-3,hy+1,2,2,"#ff6ea6"); pf(g,hx+2,hy+1,2,2,"#ff6ea6");
    pf(g,hx-4,hy+3,9,2,"#ff6ea6");
    pf(g,hx-3,hy+5,7,1,"#ff8fbc");
    pf(g,hx-2,hy+6,5,1,"#ff8fbc");
    pf(g,hx-1,hy+7,3,1,"#ffb3d2");
    pf(g,hx,hy+8,1,1,"#ffb3d2");
    g.restore();
  }
}

function drawCatEntity(g,cat,now,opt){
  opt=opt||{};
  var P=opt.palette||COATS[cat.type]||COATS.A;
  var cx=cat.rx*CELL+CELL/2;
  var gy=cat.ry*CELL+CELL-4-(cat.lift||0);
  var walking=Math.abs((cat.rx||0)-cat.x)>0.02||Math.abs((cat.ry||0)-cat.y)>0.02;
  /* 대기 모션은 '서서 가만히 있는(state==="idle" && !walking)' 고양이만.
     그 시계는 전역 now 가 아니라 이 고양이가 멈춰 있던 시간(cat._idle0)이에요.
     이동·복귀(return)·유인(lured)·추격(chase)·먹기(eat) 중에는 시계를 계속 now로 리셋해
     대기/졸음 모션이 새로 시작될 수 없게 합니다. */
  var idle=!walking&&cat.state==="idle";
  var idleElapsed=0,pose;
  if(idle){
    if(cat._idle0==null) cat._idle0=now;
    idleElapsed=Math.max(0,now-cat._idle0);
    pose=catIdlePose(cat,idleElapsed);            /* idle ↔ idle2 */
  }else{
    cat._idle0=now;
    /* 이동 중 = walk1↔walk2 · 먹는 중 = 입에 생선을 문 eat · 그 밖 = idle 고정(idle2 없음) */
    pose=walking?catWalkPose(now,true):(cat.state==="eat"?"eat":"idle");
  }
  /* 검냥이(C) 10프레임 졸다 깨는 모션: 정지 후 정확히 4초(F1 말똥) → 그 뒤 F2..F10.
     걷기·복귀·유인·추격·먹기 중에는 -1(이 모션 없음). */
  var sleep=(idle&&cat.type==="C")?sleepFrameAt(idleElapsed,0):-1;
  /* 걷기→정지 전환 순간 착지 스쿼시: 0~130ms 2px, 130~260ms 1px 크런치 */
  if(cat._wasWalk&&!walking) cat._landT=now;
  cat._wasWalk=walking;
  var landSq=0;
  if(cat._landT){ var lt=now-cat._landT; landSq=(lt<130)?2:(lt<260?1:0); }
  var emote=null;
  if(cat.state==="chase") emote="!";
  else if(cat.state==="lured") emote="?";   /* 먹이 쪽으로 걷는 동안은 호기심(?)만 — ♥는 먹기 시작하면 표시 */
  else if(cat.state==="eat") emote="heart";
  if(cat._emote!==emote){ cat._emote=emote; cat._emoteT=now; }
  drawCatAt(g,cx,gy,P,cat.dir,cat.type,now,{pose:pose,ghost:opt.ghost,noShadow:opt.noShadow,
      seed:(cat.x*7+cat.y*13),emote:emote,emoteT:cat._emoteT,spotT:cat.alertT,landSq:landSq,munch:(cat.state==="eat"),sleep:sleep});
}

/* ================= 스프라이트: 작은 인간 / 먹이 3종 =================
   human-sprite-sheet-4dir.png · food-items-3types.png의 어두운 슬레이트 배경만 투명 처리하고
   64×64 프레임 base64 PNG로 넣었어요. (인간 = 바닥 기준 정렬 · 먹이 = 프레임 중앙 정렬)
   인간 dir: 0↑(뒷모습) 1→ 2↓(정면) 3← · 먹이 kind: small 통생선보다 살짝 작게 / big / catnip */
var HUMSPR={0:"",1:"",2:"",3:""};
var FOODSPR={small:"",big:"",catnip:""};
/* 인벤토리·상세 카드용 아이콘: 보드 스프라이트(FOODSPR)와 같은 그림에서 투명 여백만 잘라낸 것.
   64px 프레임을 26px 칸에 그대로 넣으면 그림이 13px로 작아져서, 그림 영역만 24~28px에 맞춰요. */
var FOODICON={small:"",big:"",catnip:""};
var HUMIMG={}, FOODIMG={};
(function(){
  var d,k,im;
  for(d in HUMSPR){ im=new Image(); im.src="data:image/png;base64,"+HUMSPR[d]; HUMIMG[d]=im; }
  for(k in FOODSPR){ im=new Image(); im.src="data:image/png;base64,"+FOODSPR[k]; FOODIMG[k]=im; }
})();
